  'site.why.sub': 'ज़्यादातर बिल्डर गुणवत्ता का वादा करते हैं। हम इसे साबित करते हैं — ऑडिटेड प्रक्रियाओं, पारदर्शी लागतों और ऐसी वारंटियों से जो वास्तव में निभाई जाती हैं।',
