  'site.testi.eyebrow': 'ग्राहकों की कहानियाँ',
  'site.testi.title': 'परिवारों,',
  'site.testi.highlight': 'बिल्डरों और व्यवसायों का विश्वास।',
  'site.testi.sub': 'गृहस्वामी और उद्यम एक ही कारण से CREWNBUILD चुनते हैं — हम वही देते हैं जो हम वादा करते हैं।',
  'site.testi.q1': 'CREWNBUILD ने हमारा सपनों का घर बजट में और तीन हफ्ते पहले बना दिया। साप्ताहिक फोटो अपडेट से हम कभी लूप से बाहर नहीं रहे।',
