  'site.testi.q2': 'उनकी परियोजना प्रबंधन अनुशासन बेजोड़ है। मील के पत्थर पूरे, गुणवत्ता जाँची, हर रुपया हिसाब में।',
  'site.testi.r2': 'निदेशक · स्काईलाइन इंफ्रा',
  'site.testi.q3': 'अनुमतियों से लेकर पेंट तक, उन्होंने सब संभाला। पहली बार निर्माण करवाते हुए हर कदम पर मार्गदर्शन मिला।',
  'site.testi.r3': 'गृहस्वामी · सीडार क्रीक',
  'site.faq.eyebrow': 'सामान्य प्रश्न',
  'site.faq.title': 'सवाल?',
  'site.faq.highlight': 'स्पष्ट जवाब।',
  'site.faq.sub': 'निर्माण शुरू करने से पहले गृहस्वामी और व्यवसाय आमतौर पर यही पूछते हैं। आपका सवाल नहीं मिला? कभी भी लिखें।',
  'site.faq.q1': 'आपकी मूल्य निर्धारण संरचना कैसी है?',
  'site.faq.a1': 'हर परियोजना पारदर्शी, लाइन-आइटम BOQ अनुमान से शुरू होती है। शुरू करने से पहले आप लागत स्वीकार करते हैं, और मील के पत्थर आधारित भुगतान योजना से आप केवल सत्यापित कार्य के लिए भुगतान करते हैं।',
  'site.faq.q2': 'क्या आप अनुमतियाँ और मंज़ूरी संभालते हैं?',
  'site.faq.a2': 'हाँ। हमारी संपर्क टीम स्वीकृत योजनाएँ, रेरा फाइलिंग और नगर निगम की अनुमतियाँ शुरू से अंत तक संभालती है, हर चरण पर आपको अपडेट रखती है।',
  'site.faq.q3': 'सामान्य परियोजना अवधि कितनी है?',
  'site.faq.a3': 'एक मानक स्वतंत्र घर आकार और डिज़ाइन के अनुसार 8–14 महीने लेता है। वाणिज्यिक शेल 9–18 महीने। शुरू करने से पहले आपको प्रतिबद्ध कार्यक्रम मिलता है।',
  'site.faq.q4': 'क्या मैं अपनी परियोजना दूर से ट्रैक कर सकता हूँ?',
  'site.faq.a4': 'बिल्कुल। हर ग्राहक को साप्ताहिक प्रगति रिपोर्ट, फोटो अपडेट, सामग्री उपयोग और लागत ट्रैकिंग के साथ लाइव डैशबोर्ड मिलता है।',
  'site.faq.q5': 'आप कौन सी वारंटियाँ देते हैं?',
  'site.faq.a5': 'संरचनात्मक कार्यों पर 10 वर्ष और MEP प्रणालियों पर 2 वर्ष की वारंटी, सभी फिनिश पर 12 महीने की निर्माणोत्तर सेवा के साथ।',
  'site.faq.q6': 'क्या आप अपने शहरों के बाहर परियोजनाओं पर काम करते हैं?',
  'site.faq.a6': 'हम वर्तमान में हैदराबाद, बेंगलुरु, चेन्नई, पुणे और मुंबई में काम करते हैं। बड़ी वाणिज्यिक और बुनियादी ढाँचा परियोजनाओं के लिए हम देशभर में तैयार रहते हैं।',
  'site.cta.badge': 'मुफ़्त परामर्श',
  'site.cta.title': 'अपनी अगली परियोजना की नींव रखने के लिए तैयार?',
  'site.cta.sub': 'आपकी पूछताछ के 48 घंटों के भीतर मुफ़्त साइट विज़िट, पारदर्शी अनुमान और प्रतिबद्ध समयरेखा पाएँ।',

  /* ---- Site pages ---- */
  'site.about.hero.eyebrow': 'CREWNBUILD के बारे में',
  'site.about.hero.title': 'पच्चीस साल का निर्माण',
  'site.about.hero.highlight': 'कंक्रीट में विश्वास।',
  'site.about.hero.sub': '2001 में पाँच लोगों की साइट टीम से लेकर भारत के सबसे भरोसेमंद निर्माण घरों में से एक तक — हमारी कहानी उन इमारतों में लिखी है जिन्हें हमने पीछे छोड़ा है।',
  'site.about.story.eyebrow': 'हमारी कहानी',
  'site.about.story.title': 'एक साइट टीम से',
  'site.about.story.highlight': 'पूर्ण-स्तरीय निर्माण घर तक।',
  'site.about.story.p1': 'CREWNBUILD की शुरुआत 2001 में हैदराबाद में एक आवासीय निर्माण और एक सरल वादे से हुई — ग्राहक को हर रुपया, हर हफ्ते दिखाओ। वही वादा हमारा ऑपरेटिंग सिस्टम बन गया।',
  'site.about.story.p2': 'आज हम 120+ इंजीनियरों, वास्तुकारों और परियोजना प्रबंधकों को रोज़गार देते हैं जिन्होंने आवासीय, वाणिज्यिक और अवसंरचना में 850+ परियोजनाएँ पूरी की हैं। हम इन-हाउस डिज़ाइन और QA में भारी निवेश करते हैं क्योंकि हम मानते हैं कि गुणवत्ता को आउटसोर्स नहीं किया जा सकता।',
  'site.about.story.est': 'स्था. 2001',
