  'site.calculators.raw.method': 'निर्मित क्षेत्र × प्रति वर्ग फुट प्रकाशित खपत। मात्राएँ श्रेणियों में दिखाई जाती हैं क्योंकि आधारभूत थंब रूल भी श्रेणियाँ हैं — उदाहरण के लिए सीमेंट {low}–{high} बोरे प्रति वर्ग फुट। यह एक सामान्य आरसीसी फ्रेम वाले आवासीय भवन के लिए योजना अनुमान है, बिल ऑफ क्वांटिटीज़ नहीं: वास्तविक आँकड़े संरचनात्मक ड्रॉइंग, बार बेंडिंग शेड्यूल और बीओक्यू से आते हैं, और साइट पर होने वाली बर्बादी इसमें शामिल नहीं है। दरें प्रकाशित भारतीय निर्माण थंब रूल से (civiconcepts, bricknbolt, houseyog)।',
