  'site.calculators.raw.thumbRuleDisclaimer': 'ये मात्राएँ निर्माण के थंब-रूल पर आधारित सांकेतिक अनुमान हैं, विस्तृत BOQ नहीं। वास्तविक मात्राएँ स्ट्रक्चरल डिज़ाइन, ड्रॉइंग, स्पेसिफिकेशन, साइट की स्थिति और निर्माण पद्धति के अनुसार बदलती हैं। वेस्टेज (बर्बादी) शामिल नहीं है।',
