  'site.calculators.paint.method': 'पेंट योग्य क्षेत्रफल × कोट ÷ फैलाव दर। फैलाव दरें नेरोलैक की कवरेज गाइड (nerolac.com) में प्रकाशित आँकड़े हैं, जो प्रति लीटर प्रति कोट दिए गए हैं। ये एक सामान्य अनुमान हैं: वास्तविक दर डिब्बे की तकनीकी डेटा शीट पर होती है और सतह की बनावट, सोखने की क्षमता तथा पेंट लगाने के तरीके से बदलती है। CREWNBUILD के उत्पाद रिकॉर्ड में कवरेज के आँकड़े नहीं हैं, इसलिए यहाँ किसी विशेष उत्पाद का वर्णन नहीं किया जा रहा।',
