  'site.calculators.readyMix.method': 'रेडी-मिक्स कंक्रीट आयतन के हिसाब से खरीदी जाती है, इसलिए यह ढलाई का ज्यामितीय आयतन है और साथ में गिरने, अधिक खुदाई तथा पंप में होने वाले नुकसान के लिए छूट है। 5–10% की छूट वही श्रेणी है जो प्रकाशित भारतीय निर्माण संदर्भ देते हैं; इसे चुपचाप लागू करने के बजाय विकल्प के रूप में दिया गया है। कंक्रीट का ग्रेड आपूर्तिकर्ता का मिक्स डिज़ाइन है और इससे ज़रूरी आयतन नहीं बदलता, इसलिए यहाँ कोई मिक्स अनुपात नहीं माना गया।',
